    if(state.note!==undefined&&(typeof state.note!=='string'||state.note.length>2000)||state.linkedOpen!==undefined&&typeof state.linkedOpen!=='boolean')return false;
    if(state.linkedScope!==undefined&&!['NETWORK','SELECTED','VIEWPORT'].includes(state.linkedScope)||state.linkedKind!==undefined&&!['ALL','inbound','outbound','transfer'].includes(state.linkedKind))return false;
    if(state.linkedRanges!==undefined){if(!state.linkedRanges||typeof state.linkedRanges!=='object'||Array.isArray(state.linkedRanges)||Object.keys(state.linkedRanges).some(key=>!['distance','quantity'].includes(key)))return false;for(const r of Object.values(state.linkedRanges))if(!r||typeof r.unknown!=='boolean'||!r.unknown&&(!Number.isFinite(r.min)||r.min<0||r.max!==null&&(!Number.isFinite(r.max)||r.max<r.min)))return false;}
