  function bookmarkRecord(name){const state=view(),p=model.provenance,context=model.relationContext;return {id:root.crypto.randomUUID(),name,identity:bookmarkIdentity(),label:[context.scenarioName,context.periodLabel].join(' · '),comparison:{scenarioId:p.selectedScenarioId||'',...(p.referenceScenarioId?{referenceScenarioId:p.referenceScenarioId}:{}),mode:p.mode||'BOTH',leg:p.leg||'BOTH',period:p.period||'ALL',change:p.changeFilter||'ALL',nodeId:p.nodeId||''},state:{presentation:state.presentation||'relations',analysisIds:state.analysisIds||[],analysisDirection:state.analysisDirection||'ANY',activeLayerIds:state.activeLayerIds||null,center:state.center?[((state.center[0]+180)%360+360)%360-180,state.center[1]]:null,zoom:state.zoom??null,bearing:state.bearing||0,pitch:state.pitch||0,split:Boolean(state.split),comparisonLayout:state.comparisonLayout||'split',swipePosition:state.swipePosition??50,selectedEntityId:state.selectedEntityId||'',relatedOnly:Boolean(state.relatedOnly),analysisOpen:Boolean(state.analysisOpen),clusterEnabled:state.clusterEnabled!==false,lineWidthMode:state.lineWidthMode||'quantity',linkedOpen:Boolean(state.linkedOpen),linkedScope:state.linkedScope||'NETWORK',linkedKind:state.linkedKind||'ALL',linkedRanges:state.linkedRanges||{},regionGeometry:state.regionGeometry||null,regionRule:state.regionRule||'EITHER',gridSize:Number(state.gridSize)||1,gridDisplay:state.gridDisplay||'off',qualityFilter:state.qualityFilter||'ALL',note:(state.note||'').slice(0,2000)}};}
