  function analysisClick(event){
    if(owner!=='SUPPLY')return false;
    const target=event.target;
    if(target.closest('[data-p7-analysis-close]')){view().analysisOpen=false;renderAnalysis();return true;}
    if(target.closest('[data-p7-view-export]')){exportView();return true;}
    const brush=target.closest('[data-p7-brush]');if(brush){if(view().brushDragged){view().brushDragged=false;return true;}const key=brush.dataset.p7Brush,bin=linkedResult().distributions[key][Number(brush.dataset.p7Bin)];view().linkedRanges={...(view().linkedRanges||{}),[key]:{min:bin.min,max:bin.max,unknown:bin.unknown}};refreshLinked();return true;}
    const removeRange=target.closest('[data-p7-linked-remove]');if(removeRange){const ranges={...view().linkedRanges};delete ranges[removeRange.dataset.p7LinkedRemove];view().linkedRanges=ranges;refreshLinked();return true;}
    if(target.closest('[data-p7-linked-clear]')){Object.assign(view(),{analysisIds:[],analysisDirection:'ANY',multiSelect:false,linkedRanges:{},linkedScope:'NETWORK',linkedKind:'ALL',regionGeometry:null,regionNotice:'',qualityFilter:'ALL',gridDisplay:'off'});refreshLinked();return true;}
    if(target.closest('[data-p7-linked-more]')){view().linkedLimit=(view().linkedLimit||10)+20;renderAnalysis();return true;}
    const relation=target.closest('[data-p7-linked-relation]');if(relation){selectRelation(relation.dataset.p7LinkedRelation);return true;}
    if(target.closest('[data-p7-region-clear]')){view().regionGeometry=null;view().regionNotice='';refreshLinked();return true;}
    const cell=target.closest('[data-p7-grid-cell]');if(cell){const kind=view().linkedKind==='inbound'?'inbound':'outbound',grid=ns.supplyMap.fixedGrid(model,linkedResult().relations,kind,Number(view().gridSize)||1),row=grid.cells.find(c=>c.key===cell.dataset.p7GridCell);if(row){view().analysisIds=row.nodeIds;view().linkedScope='SELECTED';view().analysisDirection='INCOMING';view().gridNotice=row.nodeIds.map(id=>model.entities.find(e=>e.id===id)?.label||id).join(' · ');refreshLinked();}return true;}
    if(target.closest('[data-p7-analysis]')){view().analysisOpen=!view().analysisOpen;if(!view().analysisOpen){view().multiSelect=false;cancelArea();}renderAnalysis();updateSource();renderMode();return true;}
    if(target.closest('[data-p7-bookmarks]')){view().bookmarksOpen=!view().bookmarksOpen;renderBookmarks();return true;}
    if(target.closest('[data-p7-area]')){if(config.noWebGL||failed||!map||!ready)return true;if(areaSelection)cancelArea();else{areaSelection={};view().multiSelect=false;host.classList.add('is-selecting-area');hidePreview();}renderAnalysis();host.querySelector('[data-p7-area]')?.focus({preventScroll:true});return true;}
    if(target.closest('[data-p7-multi]')){cancelArea();view().multiSelect=!view().multiSelect;renderAnalysis();updateSource();renderMode();host.querySelector('[data-p7-multi]')?.focus({preventScroll:true});return true;}
    if(target.closest('[data-p7-analysis-clear]')){cancelArea();view().analysisIds=[];refreshSelection();return true;}
    const remove=target.closest('[data-p7-analysis-remove]');if(remove){toggleAnalysisObject(remove.dataset.p7AnalysisRemove);return true;}
    if(target.closest('[data-p7-bookmark-save]')){saveBookmark();return true;}
    const restore=target.closest('[data-p7-bookmark-restore]');if(restore){restoreBookmark(restore.dataset.p7BookmarkRestore);return true;}
    if(target.closest('[data-p7-bookmark-backup]')){downloadBookmarkBackup();return true;}
    const del=target.closest('[data-p7-bookmark-remove]');if(del){try{const rows=readBookmarks(true);writeBookmarks(rows.filter(row=>row.id!==del.dataset.p7BookmarkRemove),true);view().bookmarkNotice='';}catch(error){view().bookmarkNotice=bookmarkError(error);}renderBookmarks();host.querySelector('[data-p7-bookmark-name]')?.focus({preventScroll:true});return true;}
    return false;
  }

